from __future__ import annotations

import asyncio
from typing import Any

from provider_client import ProviderClient


def _normalize_item(raw: dict[str, Any]) -> dict[str, Any]:
    return {
        "external_id": str(raw.get("external_id", "")).strip(),
        "source": str(raw.get("source", "default")).strip().lower(),
        "priority": int(raw.get("priority", 0)),
    }


def _to_result(raw_item: dict[str, Any], provider_payload: dict[str, Any]) -> dict[str, Any]:
    if not provider_payload.get("ok"):
        return {
            "ok": False,
            "external_id": raw_item["external_id"],
            "source": raw_item["source"],
            "reason": provider_payload.get("reason", "provider_error"),
        }
    return {
        "ok": True,
        "external_id": raw_item["external_id"],
        "source": raw_item["source"],
        "name": provider_payload.get("name", ""),
        "score": int(provider_payload.get("score", 0)),
        "status": provider_payload.get("status", "unknown"),
    }


def ingest_sync(items: list[dict[str, Any]], client: ProviderClient) -> dict[str, Any]:
    normalized = [_normalize_item(item) for item in items]
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0

    for item in normalized:
        if not item["external_id"]:
            result = {"ok": False, "external_id": "", "source": item["source"], "reason": "invalid_external_id"}
            results.append(result)
            failed += 1
            continue
        payload = client.fetch_sync(item["external_id"])
        result = _to_result(item, payload)
        results.append(result)
        if result["ok"]:
            success += 1
        else:
            failed += 1

    return {
        "ok": failed == 0,
        "success": success,
        "failed": failed,
        "results": results,
    }


async def ingest_async(items: list[dict[str, Any]], client: ProviderClient) -> dict[str, Any]:
    normalized = [_normalize_item(item) for item in items]
    tasks: list[asyncio.Task] = []
    placeholders: list[dict[str, Any]] = []

    for item in normalized:
        if not item["external_id"]:
            placeholders.append(
                {"ok": False, "external_id": "", "source": item["source"], "reason": "invalid_external_id"}
            )
            continue
        tasks.append(asyncio.create_task(client.fetch_async(item["external_id"])))
        placeholders.append(item)

    payloads = await asyncio.gather(*tasks) if tasks else []
    payload_index = 0
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0

    for item in placeholders:
        if "reason" in item:
            results.append(item)
            failed += 1
            continue
        payload = payloads[payload_index]
        payload_index += 1
        result = _to_result(item, payload)
        results.append(result)
        if result["ok"]:
            success += 1
        else:
            failed += 1

    return {"ok": failed == 0, "success": success, "failed": failed, "results": results}


def ingest(items: list[dict[str, Any]], client: ProviderClient, mode: str = "sync") -> dict[str, Any]:
    normalized_mode = mode.strip().lower()
    if normalized_mode == "async":
        # Bug: async mode still dispatches sync path in legacy implementation.
        return ingest_sync(items, client)
    return ingest_sync(items, client)

