from __future__ import annotations

from typing import Any

from ingestion_service import ingest
from provider_client import ProviderClient


def run_pipeline(
    batch_payload: dict[str, Any],
    client: ProviderClient,
) -> dict[str, Any]:
    items = list(batch_payload.get("items", []))
    mode = str(batch_payload.get("mode", "sync")).strip().lower()
    trace_id = str(batch_payload.get("trace_id", "")).strip() or "trace-missing"

    if not isinstance(items, list):
        return {"ok": False, "reason": "invalid_items", "trace_id": trace_id}
    if mode not in {"sync", "async"}:
        return {"ok": False, "reason": "invalid_mode", "trace_id": trace_id}

    result = ingest(items, client, mode=mode)
    return {
        "ok": bool(result.get("ok", False)),
        "reason": "pipeline_completed",
        "trace_id": trace_id,
        "mode": mode,
        "summary": {"success": result.get("success", 0), "failed": result.get("failed", 0)},
        "results": result.get("results", []),
    }


def run_many(
    payloads: list[dict[str, Any]],
    client: ProviderClient,
) -> dict[str, Any]:
    outputs: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        output = run_pipeline(payload, client)
        outputs.append(output)
        if output.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "outputs": outputs}


def collect_external_ids(results: list[dict[str, Any]]) -> list[str]:
    ids: list[str] = []
    for item in results:
        ext = str(item.get("external_id", "")).strip()
        if ext:
            ids.append(ext)
    return ids


def summarize_result(result: dict[str, Any]) -> dict[str, Any]:
    summary = dict(result.get("summary", {}))
    details = result.get("results", [])
    return {
        "trace_id": result.get("trace_id", ""),
        "mode": result.get("mode", ""),
        "success": int(summary.get("success", 0)),
        "failed": int(summary.get("failed", 0)),
        "external_ids": collect_external_ids(details if isinstance(details, list) else []),
    }


def summarize_many(results: list[dict[str, Any]]) -> dict[str, Any]:
    total_success = 0
    total_failed = 0
    traces: list[str] = []
    for result in results:
        summary = summarize_result(result)
        total_success += int(summary.get("success", 0))
        total_failed += int(summary.get("failed", 0))
        traces.append(str(summary.get("trace_id", "")))
    return {
        "total_success": total_success,
        "total_failed": total_failed,
        "trace_ids": traces,
    }

