from __future__ import annotations

from time import sleep
from typing import Any


class ProviderClient:
    def __init__(self) -> None:
        self._responses: dict[str, dict[str, Any]] = {}
        self._calls: list[str] = []

    def seed(self, responses: dict[str, dict[str, Any]]) -> None:
        self._responses = {str(key): dict(value) for key, value in responses.items()}
        self._calls.clear()

    def fetch_sync(self, external_id: str) -> dict[str, Any]:
        key = str(external_id).strip()
        if not key:
            return {"ok": False, "reason": "invalid_external_id"}
        self._calls.append(key)
        sleep(0.001)
        payload = self._responses.get(key)
        if payload is None:
            return {"ok": False, "reason": "not_found", "external_id": key}
        return {
            "ok": True,
            "external_id": key,
            "name": str(payload.get("name", "")).strip(),
            "score": int(payload.get("score", 0)),
            "status": str(payload.get("status", "unknown")).strip().lower(),
        }

    async def fetch_async(self, external_id: str) -> dict[str, Any]:
        # Async wrapper expected to evolve in refactor.
        return self.fetch_sync(external_id)

    def call_count(self) -> int:
        return len(self._calls)

    def called_ids(self) -> list[str]:
        return list(self._calls)

    def clear_calls(self) -> None:
        self._calls.clear()

    def has_response(self, external_id: str) -> bool:
        key = str(external_id).strip()
        return key in self._responses

    def snapshot(self) -> dict[str, Any]:
        return {
            "responses": {key: dict(value) for key, value in self._responses.items()},
            "calls": list(self._calls),
        }

    def upsert_response(self, external_id: str, payload: dict[str, Any]) -> None:
        key = str(external_id).strip()
        if not key:
            raise ValueError("external_id is required")
        self._responses[key] = dict(payload)

    def remove_response(self, external_id: str) -> bool:
        key = str(external_id).strip()
        if not key:
            return False
        if key in self._responses:
            del self._responses[key]
            return True
        return False

    def response_count(self) -> int:
        return len(self._responses)

    def list_ids(self) -> list[str]:
        return sorted(self._responses.keys())

    def last_called_id(self) -> str:
        if not self._calls:
            return ""
        return self._calls[-1]

    def was_called(self, external_id: str) -> bool:
        key = str(external_id).strip()
        return key in self._calls

