from pipeline import run_pipeline
from provider_client import ProviderClient


def _client() -> ProviderClient:
    client = ProviderClient()
    client.seed(
        {
            "x-1": {"name": "Alpha", "score": 10, "status": "ready"},
            "x-2": {"name": "Beta", "score": 20, "status": "ready"},
        }
    )
    return client


def test_happy_path_async_mode_uses_async_fetch_path():
    client = _client()
    payload = {
        "trace_id": "t-1",
        "mode": "async",
        "items": [{"external_id": "x-1", "source": "crm", "priority": 1}],
    }
    result = run_pipeline(payload, client)
    assert result["ok"] is True
    assert result["summary"]["success"] == 1
    assert client.call_count() == 0


def test_edge_case_missing_external_id_rejected():
    client = _client()
    payload = {
        "trace_id": "t-2",
        "mode": "sync",
        "items": [{"external_id": "", "source": "crm", "priority": 1}],
    }
    result = run_pipeline(payload, client)
    assert result["ok"] is False
    assert result["summary"]["failed"] == 1


def test_boundary_condition_single_item_sync_success():
    client = _client()
    payload = {
        "trace_id": "t-3",
        "mode": "sync",
        "items": [{"external_id": "x-2", "source": "crm", "priority": 0}],
    }
    result = run_pipeline(payload, client)
    assert result["ok"] is True
    assert result["summary"]["success"] == 1


def test_unexpected_input_invalid_mode_rejected():
    client = _client()
    payload = {"trace_id": "t-4", "mode": "stream", "items": []}
    result = run_pipeline(payload, client)
    assert result["ok"] is False
    assert result["reason"] == "invalid_mode"
